import Foundation
import Testing
@testable import ZGate

/// Tests for `CredentialStore` — loading, decrypting, and typing the zcode
/// scratch credential store. All fixtures are synthetic (generated by
/// `Fixtures/synthetic-store/make-fixture.sh` and committed); no test ever
/// reads the real `~/.zcode-scratch-v3` store.
struct CredentialStoreTests {

    // MARK: - Fixture plumbing

    /// Marker class so the test bundle can be located portably.
    private final class BundleToken {}

    /// Directory holding the committed synthetic store (`credentials.json` +
    /// `secret.txt`). The test host is sandboxed, so fixtures ship as bundle
    /// resources (synchronized groups pick up `Fixtures/` automatically); the
    /// source-tree fallback covers unsandboxed runners.
    static let fixtureDirectory: URL = {
        let bundle = Bundle(for: BundleToken.self)
        let candidates = [
            bundle.resourceURL,
            bundle.resourceURL?.appendingPathComponent("Fixtures/synthetic-store"),
            bundle.resourceURL?.appendingPathComponent("synthetic-store"),
            URL(fileURLWithPath: #filePath).deletingLastPathComponent()
                .appendingPathComponent("Fixtures/synthetic-store"),
        ]
        // The source-tree fallback is last: prefer the copied bundle resource.
        return candidates.compactMap { $0 }.first { dir in
            FileManager.default.fileExists(atPath: dir.appendingPathComponent("credentials.json").path)
        } ?? candidates[0]!
    }()

    /// Known synthetic values — must match make-fixture.sh.
    private static let accessTokenExp: Double = 1_763_003_600
    private static let syntheticOrganizationId = "11111111-2222-3333-4444-555555555555"
    private static let syntheticProjectId = "22222222-3333-4444-5555-666666666666"
    private static let syntheticAPIKeyId = "89abcdef89abcdef89abcdef89abcdef"
    /// First field in the store's sorted key order (validation order contract).
    private static let firstSortedField = "oauth:active_provider"

    private static func makeTempDirectory() throws -> URL {
        let dir = FileManager.default.temporaryDirectory
            .appendingPathComponent("zgate-credentialstore-\(UUID().uuidString)", isDirectory: true)
        try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        return dir
    }

    /// Which segment of an envelope's `<iv>.<tag>.<ct>` blob to corrupt.
    private enum EnvelopeSegment { case tag, ciphertext }

    /// Copies the synthetic store into `dir`, substituting one character in the
    /// given segment of the access token's blob. Same length, so the envelope
    /// stays structurally valid and only authentication fails.
    private static func writeTamperedStore(into dir: URL, segment: EnvelopeSegment) throws -> URL {
        let storeURL = dir.appendingPathComponent("credentials.json")
        let data = try Data(contentsOf: fixtureDirectory.appendingPathComponent("credentials.json"))
        var fields = try JSONDecoder().decode([String: String].self, from: data)
        guard let envelope = fields[CredentialStore.accessTokenField] else {
            throw CredentialError.missingField(name: CredentialStore.accessTokenField)
        }
        var parts = envelope.split(separator: ":", omittingEmptySubsequences: false).map(String.init)
        var blob = parts[parts.count - 1].split(separator: ".", omittingEmptySubsequences: false).map(String.init)
        let index = segment == .tag ? 1 : 2
        blob[index] = Self.flipFirstCharacter(of: blob[index])
        parts[parts.count - 1] = blob.joined(separator: ".")
        fields[CredentialStore.accessTokenField] = parts.joined(separator: ":")
        try JSONEncoder().encode(fields).write(to: storeURL)
        return storeURL
    }

    /// Substitutes the first character (same length either way).
    private static func flipFirstCharacter(of string: String) -> String {
        guard let first = string.first else { return string }
        return (first == "A" ? "B" : "A") + string.dropFirst()
    }

    // MARK: - Decryption

    @Test func roundTripDecryptsEveryEnvelope() throws {
        let store = try CredentialStore(fixture: .synthetic)

        let jwt = try store.zcodeJwtToken()
        #expect(jwt.split(separator: ".").count == 3)

        let access = try store.accessToken()
        #expect(access.split(separator: ".").count == 3)

        let location = try #require(try store.projectKeyLocation())
        #expect(location.organizationId == Self.syntheticOrganizationId)
        #expect(location.projectId == Self.syntheticProjectId)
        #expect(location.apiKeyId == Self.syntheticAPIKeyId)
        #expect(location.rawJSON.contains(Self.syntheticProjectId))

        #expect(try store.value(for: "oauth:active_provider") == "zai")
    }

    /// Writes a one-field plaintext store (passthrough values need no secret
    /// agreement) so location-shape tests can pick the exact field and value.
    private static func writePlaintextStore(
        into dir: URL, field: String, value: String
    ) throws -> (storeURL: URL, secretURL: URL) {
        let storeURL = dir.appendingPathComponent("credentials.json")
        let secretURL = dir.appendingPathComponent("secret.txt")
        try JSONEncoder().encode([field: value]).write(to: storeURL)
        try Data("any-secret".utf8).write(to: secretURL)
        return (storeURL, secretURL)
    }

    /// The percent-encoded field name the real store uses — the identity
    /// array lives in the NAME; the accessor must ignore it.
    private static func locationFieldName() throws -> String {
        let array = #"["https://api.z.ai","zai","# + Self.syntheticOrganizationId
            + #",null,1,"default"]"#
        let encoded = try #require(array.addingPercentEncoding(withAllowedCharacters: .alphanumerics))
        return CredentialStore.projectKeyLocationFieldPrefix + encoded
    }

    @Test func locationValueObjectParsesAndNamePayloadIsIgnored() throws {
        let dir = try Self.makeTempDirectory()
        defer { try? FileManager.default.removeItem(at: dir) }
        let field = try Self.locationFieldName()
        let (storeURL, secretURL) = try Self.writePlaintextStore(
            into: dir, field: field,
            value: #"{"organizationId":"\#(Self.syntheticOrganizationId)","projectId":"\#(Self.syntheticProjectId)","apiKeyId":"\#(Self.syntheticAPIKeyId)"}"#)

        let store = try CredentialStore(storeURL: storeURL, secretURL: secretURL)
        let location = try #require(try store.projectKeyLocation())
        #expect(location.organizationId == Self.syntheticOrganizationId)
        #expect(location.projectId == Self.syntheticProjectId)
        #expect(location.apiKeyId == Self.syntheticAPIKeyId)
    }

    @Test func arrayShapedLocationValueThrowsMalformedValue() throws {
        let dir = try Self.makeTempDirectory()
        defer { try? FileManager.default.removeItem(at: dir) }
        let field = try Self.locationFieldName()
        // The pre-fix belief: the array as the VALUE. The live store keeps it
        // in the field name — such a value is malformed now.
        let (storeURL, secretURL) = try Self.writePlaintextStore(
            into: dir, field: field,
            value: #"["https://api.z.ai","zai","\#(Self.syntheticOrganizationId)",null,1,"default"]"#)

        let store = try CredentialStore(storeURL: storeURL, secretURL: secretURL)
        #expect(throws: CredentialError.malformedValue(
            field: field,
            reason: "location value is not a {organizationId, projectId, apiKeyId} JSON object")
        ) {
            try store.projectKeyLocation()
        }
    }

    @Test func storeWithoutLocationFieldYieldsNil() throws {
        let dir = try Self.makeTempDirectory()
        defer { try? FileManager.default.removeItem(at: dir) }
        let (storeURL, secretURL) = try Self.writePlaintextStore(
            into: dir, field: CredentialStore.accessTokenField, value: "any-token")

        let store = try CredentialStore(storeURL: storeURL, secretURL: secretURL)
        #expect(try store.projectKeyLocation() == nil)
    }

    @Test func tamperedTagThrowsDecryptFailed() throws {
        let dir = try Self.makeTempDirectory()
        defer { try? FileManager.default.removeItem(at: dir) }
        let storeURL = try Self.writeTamperedStore(into: dir, segment: .tag)

        // Fingerprint still matches (untouched); only the GCM auth fails.
        #expect(throws: CredentialError.decryptFailed(field: CredentialStore.accessTokenField)) {
            try CredentialStore(storeURL: storeURL,
                                secretURL: Self.fixtureDirectory.appendingPathComponent("secret.txt"))
        }
    }

    @Test func tamperedCiphertextThrowsDecryptFailed() throws {
        let dir = try Self.makeTempDirectory()
        defer { try? FileManager.default.removeItem(at: dir) }
        let storeURL = try Self.writeTamperedStore(into: dir, segment: .ciphertext)

        #expect(throws: CredentialError.decryptFailed(field: CredentialStore.accessTokenField)) {
            try CredentialStore(storeURL: storeURL,
                                secretURL: Self.fixtureDirectory.appendingPathComponent("secret.txt"))
        }
    }

    @Test func wrongSecretThrowsFingerprintMismatch() throws {
        let dir = try Self.makeTempDirectory()
        defer { try? FileManager.default.removeItem(at: dir) }
        try FileManager.default.copyItem(at: Self.fixtureDirectory.appendingPathComponent("credentials.json"),
                                         to: dir.appendingPathComponent("credentials.json"))
        try Data("a-different-secret".utf8).write(to: dir.appendingPathComponent("secret.txt"))

        // Validation walks fields in sorted key order, so the mismatch is
        // reported against the store's first encrypted field.
        #expect(throws: CredentialError.fingerprintMismatch(field: Self.firstSortedField)) {
            try CredentialStore(storeURL: dir.appendingPathComponent("credentials.json"),
                                secretURL: dir.appendingPathComponent("secret.txt"))
        }
    }

    @Test func malformedEnvelopesThrowMalformedValue() throws {
        let cases: [String: String] = [
            "os-envelope": "enc:v2:os:000000000000000000000000:AAAA.BBBB.CCCC",
            "short-fingerprint": "enc:v2:env:abc:AAAA.BBBB.CCCC",
            "two-parts": "enc:v2:env:000000000000000000000000:AAAA.BBBB",
            "bad-base64url": "enc:v2:env:000000000000000000000000:AA*A.BBBB.CCCC",
        ]
        for (field, envelope) in cases {
            let dir = try Self.makeTempDirectory()
            defer { try? FileManager.default.removeItem(at: dir) }
            try JSONEncoder().encode([field: envelope]).write(to: dir.appendingPathComponent("credentials.json"))
            try Data("any-secret".utf8).write(to: dir.appendingPathComponent("secret.txt"))

            do {
                _ = try CredentialStore(storeURL: dir.appendingPathComponent("credentials.json"),
                                        secretURL: dir.appendingPathComponent("secret.txt"))
                Issue.record("expected malformedValue for field \(field)")
            } catch let error as CredentialError {
                guard case CredentialError.malformedValue(let errorField, _) = error else {
                    Issue.record("expected malformedValue for field \(field), got \(error)")
                    return
                }
                #expect(errorField == field)
            }
        }
    }

    @Test func plaintextValuesPassThrough() throws {
        let dir = try Self.makeTempDirectory()
        defer { try? FileManager.default.removeItem(at: dir) }
        try Data(#"{"oauth:active_provider":"zai"}"#.utf8)
            .write(to: dir.appendingPathComponent("credentials.json"))
        try Data("any-secret".utf8).write(to: dir.appendingPathComponent("secret.txt"))

        let store = try CredentialStore(storeURL: dir.appendingPathComponent("credentials.json"),
                                        secretURL: dir.appendingPathComponent("secret.txt"))
        #expect(try store.value(for: "oauth:active_provider") == "zai")
        #expect(throws: CredentialError.missingField(name: CredentialStore.accessTokenField)) {
            try store.accessToken()
        }
    }

    // MARK: - Expiry

    @Test func accessTokenExpiryParsesUnpaddedPayload() throws {
        let store = try CredentialStore(fixture: .synthetic)
        let expiry = try #require(try store.accessTokenExpiry())
        #expect(expiry == Date(timeIntervalSince1970: Self.accessTokenExp))

        // The fixture deliberately produces payload segments whose length is
        // not a multiple of 4 — a decode that required padding would fail here.
        let payloadSegment = try store.accessToken().split(separator: ".").map(String.init)[1]
        #expect(payloadSegment.count % 4 != 0)
    }

    @Test func jwtExpiryToleratesMissingExpAndMillisecondEpochs() throws {
        func jwt(payload: String) -> String {
            [Base64URL.encode(Data(#"{"alg":"none"}"#.utf8)),
             Base64URL.encode(Data(payload.utf8)),
             "sig"].joined(separator: ".")
        }

        #expect(try CredentialStore.jwtExpiry(of: jwt(payload: #"{"sub":"x"}"#), field: "test") == nil)
        #expect(try CredentialStore.jwtExpiry(of: jwt(payload: #"{"exp":1763003600}"#), field: "test")
                == Date(timeIntervalSince1970: 1_763_003_600))
        #expect(try CredentialStore.jwtExpiry(of: jwt(payload: #"{"exp":1763003600123}"#), field: "test")
                == Date(timeIntervalSince1970: 1_763_003_600.123))

        do {
            _ = try CredentialStore.jwtExpiry(of: "not-a-jwt", field: "test")
            Issue.record("expected malformedValue for a non-JWT string")
        } catch let error as CredentialError {
            guard case CredentialError.malformedValue = error else {
                Issue.record("expected malformedValue, got \(error)")
                return
            }
        }
    }

    // MARK: - Missing files

    @Test func missingStoreFileNamesPathAndLoginRemedy() throws {
        let dir = try Self.makeTempDirectory()
        defer { try? FileManager.default.removeItem(at: dir) }
        let storeURL = dir.appendingPathComponent("credentials.json")
        let secretURL = dir.appendingPathComponent("secret.txt")
        try Data("x".utf8).write(to: secretURL)

        do {
            _ = try CredentialStore(storeURL: storeURL, secretURL: secretURL)
            Issue.record("expected notFound for missing store file")
        } catch let error as CredentialError {
            #expect(error == CredentialError.notFound(path: storeURL.path))
            let message = (error as LocalizedError).errorDescription ?? ""
            #expect(message.contains(storeURL.path))
            #expect(message.contains("login zai"))
        }
    }

    @Test func missingSecretFileNamesPathAndLoginRemedy() throws {
        let dir = try Self.makeTempDirectory()
        defer { try? FileManager.default.removeItem(at: dir) }
        let storeURL = dir.appendingPathComponent("credentials.json")
        let secretURL = dir.appendingPathComponent("secret.txt")
        try Data("{}".utf8).write(to: storeURL)

        do {
            _ = try CredentialStore(storeURL: storeURL, secretURL: secretURL)
            Issue.record("expected notFound for missing secret file")
        } catch let error as CredentialError {
            #expect(error == CredentialError.notFound(path: secretURL.path))
            let message = (error as LocalizedError).errorDescription ?? ""
            #expect(message.contains(secretURL.path))
            #expect(message.contains("login zai"))
        }
    }

    // MARK: - base64url (RFC 4648 §5)

    @Test func base64URLMatchesRFC4648Section5Vectors() {
        let vectors: [(plain: String, encoded: String)] = [
            ("", ""),
            ("f", "Zg"),
            ("fo", "Zm8"),
            ("foo", "Zm9v"),
            ("foob", "Zm9vYg"),
            ("fooba", "Zm9vYmE"),
            ("foobar", "Zm9vYmFy"),
            // "Zm9vYQ" (unpadded, length 6 — the task brief's vector) is the
            // encoding of the 4-byte "fooa", included for the unpadded form.
            ("fooa", "Zm9vYQ"),
        ]
        for vector in vectors {
            let data = Data(vector.plain.utf8)
            #expect(Base64URL.encode(data) == vector.encoded)
            #expect(Base64URL.decode(vector.encoded) == data)
        }

        // The url-safe alphabet replaces '+' and '/'.
        #expect(Base64URL.encode(Data([0xfb, 0xff, 0xbf])) == "-_-_")
        // Padded input is tolerated; unpadded is the wire format.
        #expect(Base64URL.decode("Zm9vYQ") == Base64URL.decode("Zm9vYQ=="))
        // Invalid characters are rejected, not silently skipped.
        #expect(Base64URL.decode("Zm9v*Q") == nil)

        // Round-trip across a range of lengths and byte values.
        for length in 0...40 {
            let data = Data((0..<length).map { UInt8(truncatingIfNeeded: $0 &* 31 &+ 7) })
            #expect(Base64URL.decode(Base64URL.encode(data)) == data)
        }
    }
}

// MARK: - Envelope write path (item 4: in-app login)

extension CredentialStoreTests {

    private func makeBase() throws -> URL {
        try Self.makeTempDirectory()
    }

    @Test func saveZaiLoginRoundTripsThroughReadPath() throws {
        // MANDATORY (brief item 4): seal with a synthetic secret → read
        // back via the real CredentialStore decrypt → fields equal.
        let base = try makeBase()
        defer { try? FileManager.default.removeItem(at: base) }

        try CredentialStore.saveZaiLogin(
            accessToken: "synthetic-access-jwt",
            zcodeJwtToken: "synthetic-identity-jwt",
            userInfoJSON: #"{"id":"synthetic-user"}"#,
            base: base)

        let store = try CredentialStore(base: base)
        #expect(try store.accessToken() == "synthetic-access-jwt")
        #expect(try store.zcodeJwtToken() == "synthetic-identity-jwt")
        #expect(try store.value(for: CredentialStore.userInfoField)
            == #"{"id":"synthetic-user"}"#)
        #expect(try store.value(for: CredentialStore.activeProviderField) == "zai")
        // First write on an empty store: revision 0 → 1.
        #expect(try store.value(for: CredentialStore.sessionRevisionField) == "1")
    }

    @Test func savePreservesProjectKeyLocationsAndBumpsRevision() throws {
        let base = try makeBase()
        defer { try? FileManager.default.removeItem(at: base) }
        // Seed the base with the committed synthetic store (envelopes
        // sealed with the fixture secret — the write must reuse it).
        let v2 = base.appendingPathComponent(".zcode/v2", isDirectory: true)
        try FileManager.default.createDirectory(at: v2, withIntermediateDirectories: true)
        try FileManager.default.copyItem(
            at: Self.fixtureDirectory.appendingPathComponent("credentials.json"),
            to: v2.appendingPathComponent("credentials.json"))
        try FileManager.default.copyItem(
            at: Self.fixtureDirectory.appendingPathComponent("secret.txt"),
            to: base.appendingPathComponent("secret.txt"))

        try CredentialStore.saveZaiLogin(
            accessToken: "second-login-access",
            zcodeJwtToken: "second-login-identity",
            userInfoJSON: "{}",
            base: base)
        try CredentialStore.saveZaiLogin(
            accessToken: "third-login-access",
            zcodeJwtToken: "third-login-identity",
            userInfoJSON: "{}",
            base: base)

        // The preserved location entry still resolves, revision bumped 0→2.
        let store = try CredentialStore(base: base)
        #expect(try store.accessToken() == "third-login-access")
        #expect(try store.projectKeyLocation()?.apiKeyId == Self.syntheticAPIKeyId)
        #expect(try store.value(for: CredentialStore.sessionRevisionField) == "2")
        // The location field NAME (percent-encoded identity array) is
        // preserved verbatim.
        let raw = try JSONDecoder().decode(
            [String: String].self,
            from: Data(contentsOf: base.appendingPathComponent(".zcode/v2/credentials.json")))
        #expect(raw.keys.contains { $0.hasPrefix(CredentialStore.projectKeyLocationFieldPrefix) })
    }

    @Test func writtenStoreRejectedUnderDifferentSecret() throws {
        let base = try makeBase()
        defer { try? FileManager.default.removeItem(at: base) }
        try CredentialStore.saveZaiLogin(
            accessToken: "synthetic-access-jwt",
            zcodeJwtToken: "synthetic-identity-jwt",
            userInfoJSON: "{}",
            base: base)
        // Swap the secret the store was sealed under (the colocated file —
        // resolution candidate #1): the envelopes' fingerprints no longer
        // match — the read path must reject, not mis-decrypt.
        let colocated = base.appendingPathComponent(".zcode/v2/credential-secret")
        try Data("a-different-secret".utf8).write(to: colocated)
        #expect(throws: CredentialError.fingerprintMismatch(
            field: CredentialStore.activeProviderField)) {
            try CredentialStore(base: base)
        }
    }

    @Test func saveWrites0600WithNoTempLeftovers() throws {
        let base = try makeBase()
        defer { try? FileManager.default.removeItem(at: base) }
        try CredentialStore.saveZaiLogin(
            accessToken: "a", zcodeJwtToken: "i", userInfoJSON: "{}", base: base)

        let v2 = base.appendingPathComponent(".zcode/v2", isDirectory: true)
        let storeURL = v2.appendingPathComponent("credentials.json")
        let secretURL = v2.appendingPathComponent("credential-secret")
        let permissions = { (url: URL) -> Int in
            ((try? FileManager.default.attributesOfItem(atPath: url.path))?[.posixPermissions] as? NSNumber)?.intValue ?? 0
        }
        #expect(permissions(storeURL) & 0o777 == 0o600)
        #expect(permissions(secretURL) & 0o777 == 0o600)
        // No temporary files survive the atomic rename; the secret lives
        // in the CLI's colocated location (nothing at <base>/secret.txt).
        let v2Entries = try FileManager.default.contentsOfDirectory(atPath: v2.path)
        #expect(Set(v2Entries) == ["credentials.json", "credential-secret"])
        let baseEntries = try FileManager.default.contentsOfDirectory(atPath: base.path)
        #expect(baseEntries == [".zcode"])
    }

    @Test func saveRejectsStaleExpectedRevision() throws {
        let base = try makeBase()
        defer { try? FileManager.default.removeItem(at: base) }
        try CredentialStore.saveZaiLogin(
            accessToken: "a", zcodeJwtToken: "i", userInfoJSON: "{}", base: base)
        // Current revision is 1; a writer that read revision 0 must lose
        // the CAS instead of clobbering.
        #expect(throws: CredentialWriteError.revisionConflict(expected: 0, found: 1)) {
            try CredentialStore.saveZaiLogin(
                accessToken: "b", zcodeJwtToken: "j", userInfoJSON: "{}",
                base: base, expectedRevision: 0)
        }
        // The store is untouched by the conflicted write.
        let store = try CredentialStore(base: base)
        #expect(try store.accessToken() == "a")
    }

    // MARK: - Poisoned-store write edge (fast-follow F3: store exists,
    // secret missing)

    /// Seeds `<base>/.zcode/v2/credentials.json` from the committed fixture
    /// WITHOUT the secret — the poisoned precondition: every envelope is
    /// sealed under a secret that no longer exists, so nothing in the file
    /// can ever be decrypted again.
    private func seedStoreWithoutSecret(_ base: URL) throws -> URL {
        let v2 = base.appendingPathComponent(".zcode/v2", isDirectory: true)
        try FileManager.default.createDirectory(at: v2, withIntermediateDirectories: true)
        try FileManager.default.copyItem(
            at: Self.fixtureDirectory.appendingPathComponent("credentials.json"),
            to: v2.appendingPathComponent("credentials.json"))
        return v2
    }

    @Test func saveOnStoreWithoutSecretQuarantinesAndWritesCleanStore() throws {
        let base = try makeBase()
        defer { try? FileManager.default.removeItem(at: base) }
        let fixtureStoreURL = Self.fixtureDirectory.appendingPathComponent("credentials.json")
        let v2 = try seedStoreWithoutSecret(base)

        let result = try CredentialStore.saveZaiLogin(
            accessToken: "fresh-access-jwt",
            zcodeJwtToken: "fresh-identity-jwt",
            userInfoJSON: "{}",
            base: base)

        // The unreadable file is preserved aside under the deterministic
        // quarantine name — a user who later recovers the old secret can
        // still restore it.
        #expect(result.quarantinedUnreadableStore)
        let quarantineURL = v2.appendingPathComponent("credentials.json.unreadable-store")
        #expect(try Data(contentsOf: quarantineURL) == Data(contentsOf: fixtureStoreURL))

        // The fresh store loads cleanly through the real read path — no
        // dead preserved envelopes, revision restarts at 1.
        let store = try CredentialStore(base: base)
        #expect(try store.accessToken() == "fresh-access-jwt")
        #expect(try store.zcodeJwtToken() == "fresh-identity-jwt")
        #expect(try store.value(for: CredentialStore.activeProviderField) == "zai")
        #expect(try store.value(for: CredentialStore.sessionRevisionField) == "1")
        #expect(try store.projectKeyLocation() == nil)
        let raw = try JSONDecoder().decode(
            [String: String].self,
            from: Data(contentsOf: v2.appendingPathComponent("credentials.json")))
        #expect(!raw.keys.contains { $0.hasPrefix(CredentialStore.projectKeyLocationFieldPrefix) })

        // The honest gap is reported: the resulting store has no location.
        #expect(result.storeLacksProjectLocation)
    }

    @Test func quarantineIsReplacedOnASecondPoisonedOccurrence() throws {
        let base = try makeBase()
        defer { try? FileManager.default.removeItem(at: base) }
        let v2 = try seedStoreWithoutSecret(base)
        let storeURL = v2.appendingPathComponent("credentials.json")
        let quarantineURL = v2.appendingPathComponent("credentials.json.unreadable-store")

        // First poisoned occurrence quarantines the unreadable bytes.
        _ = try CredentialStore.saveZaiLogin(
            accessToken: "first-login", zcodeJwtToken: "identity", userInfoJSON: "{}",
            base: base)
        #expect(try FileManager.default.fileExists(atPath: quarantineURL.path))

        // Re-poison (the fresh secret disappears again): the second
        // occurrence REPLACES the quarantine instead of failing or
        // accumulating files.
        try FileManager.default.removeItem(
            at: v2.appendingPathComponent("credential-secret"))
        try Data(#"{"second":"dead-store"}"#.utf8).write(to: storeURL)
        _ = try CredentialStore.saveZaiLogin(
            accessToken: "second-login", zcodeJwtToken: "identity", userInfoJSON: "{}",
            base: base)
        #expect(try String(contentsOf: quarantineURL, encoding: .utf8)
            == #"{"second":"dead-store"}"#)
        // Exactly the live store, its fresh colocated secret, and one
        // quarantine file — no leftovers.
        #expect(try FileManager.default.contentsOfDirectory(atPath: v2.path).sorted()
            == ["credential-secret", "credentials.json", "credentials.json.unreadable-store"])
        // The second clean write is intact and loadable.
        let store = try CredentialStore(base: base)
        #expect(try store.accessToken() == "second-login")
        #expect(try store.value(for: CredentialStore.sessionRevisionField) == "1")
    }

    @Test func saveResultReportsLocationPresenceAndQuarantine() throws {
        // Virgin store: nothing quarantined, and the login-only field set
        // carries no location entry.
        let virginBase = try makeBase()
        defer { try? FileManager.default.removeItem(at: virginBase) }
        let virgin = try CredentialStore.saveZaiLogin(
            accessToken: "a", zcodeJwtToken: "i", userInfoJSON: "{}", base: virginBase)
        #expect(virgin == ZaiLoginSaveResult(
            storeLacksProjectLocation: true, quarantinedUnreadableStore: false))

        // Store + secret seeded from the fixture: the location entry
        // survives the write, so no gap is reported.
        let seededBase = try makeBase()
        defer { try? FileManager.default.removeItem(at: seededBase) }
        _ = try seedStoreWithoutSecret(seededBase)
        try FileManager.default.copyItem(
            at: Self.fixtureDirectory.appendingPathComponent("secret.txt"),
            to: seededBase.appendingPathComponent("secret.txt"))
        let seeded = try CredentialStore.saveZaiLogin(
            accessToken: "a", zcodeJwtToken: "i", userInfoJSON: "{}", base: seededBase)
        #expect(seeded == ZaiLoginSaveResult(
            storeLacksProjectLocation: false, quarantinedUnreadableStore: false))
    }

    // MARK: - CLI co-tenancy (os envelopes + Keychain secret)

    private struct FakeKeychain: KeychainReading {
        var keys: [String: Data] = [:]
        var deniedAccounts: Set<String> = []
        var unavailableAccounts: Set<String> = []

        func osSecretKey(account: String) throws -> Data {
            if deniedAccounts.contains(account) {
                throw KeychainSecretFailure.accessDenied
            }
            if unavailableAccounts.contains(account) {
                throw KeychainSecretFailure.unavailable
            }
            guard let key = keys[account] else {
                throw KeychainSecretFailure.itemNotFound
            }
            return key
        }
    }

    /// Builds a CLI-shaped store: os envelopes under a synthetic 32-byte
    /// key, a location entry, revision `revision`, and NO secret file —
    /// exactly what a standard logged-in zcode CLI leaves behind.
    private func seedOSStore(in base: URL, rawKey: Data, revision: Int) throws -> URL {
        let v2 = base.appendingPathComponent(".zcode/v2", isDirectory: true)
        try FileManager.default.createDirectory(at: v2, withIntermediateDirectories: true)
        let key = CredentialStore.StoreKey(flavor: .os, keyData: rawKey, secretData: nil)
        let locationJSON = """
        {"organizationId":"\(Self.syntheticOrganizationId)","projectId":"\(Self.syntheticProjectId)","apiKeyId":"\(Self.syntheticAPIKeyId)"}
        """
        var fields: [String: String] = [:]
        fields[CredentialStore.accessTokenField] = try CredentialStore.sealEnvelope(
            value: "synthetic-os-access.jwt.payload", key: key)
        fields[CredentialStore.zcodeJwtTokenField] = try CredentialStore.sealEnvelope(
            value: "synthetic-os-identity.jwt.payload", key: key)
        fields[CredentialStore.activeProviderField] = try CredentialStore.sealEnvelope(
            value: "zai", key: key)
        fields[CredentialStore.userInfoField] = try CredentialStore.sealEnvelope(
            value: "{}", key: key)
        fields[CredentialStore.sessionRevisionField] = try CredentialStore.sealEnvelope(
            value: String(revision), key: key)
        fields[CredentialStore.projectKeyLocationFieldPrefix + "%5B%22synthetic%22%5D"] =
            try CredentialStore.sealEnvelope(value: locationJSON, key: key)
        let storeURL = v2.appendingPathComponent("credentials.json")
        try JSONEncoder().encode(fields).write(to: storeURL)
        return storeURL
    }

    @Test func osEnvelopeStoreReadsViaKeychainKey() throws {
        let base = try makeBase()
        defer { try? FileManager.default.removeItem(at: base) }
        let rawKey = Data((0..<32).map { UInt8($0 & 0xFF) })
        let storeURL = try seedOSStore(in: base, rawKey: rawKey, revision: 7)

        let account = CredentialStore.keychainAccount(forStoreAt: storeURL)
        let store = try CredentialStore(
            storeURL: storeURL,
            secretURL: base.appendingPathComponent("secret.txt"),
            keychain: FakeKeychain(keys: [account: rawKey]))

        #expect(try store.accessToken() == "synthetic-os-access.jwt.payload")
        #expect(try store.projectKeyLocation()?.organizationId == Self.syntheticOrganizationId)
        #expect(store.sealingKey?.flavor == .os)
    }

    @Test func saveAdoptsReadableOSStoreWithoutQuarantineOrSecretFile() throws {
        let base = try makeBase()
        defer { try? FileManager.default.removeItem(at: base) }
        let rawKey = Data((0..<32).map { UInt8(($0 * 7) & 0xFF) })
        let storeURL = try seedOSStore(in: base, rawKey: rawKey, revision: 7)
        let keychain = FakeKeychain(
            keys: [CredentialStore.keychainAccount(forStoreAt: storeURL): rawKey])

        let result = try CredentialStore.saveZaiLogin(
            accessToken: "fresh-access.jwt.payload",
            zcodeJwtToken: "fresh-identity.jwt.payload",
            userInfoJSON: "{}",
            base: base,
            keychain: keychain)

        // No quarantine, no secret file — the CLI's Keychain stays the
        // only secret source.
        #expect(!result.quarantinedUnreadableStore)
        #expect(!FileManager.default.fileExists(
            atPath: base.appendingPathComponent("secret.txt").path))
        #expect(!FileManager.default.fileExists(
            atPath: storeURL.deletingLastPathComponent()
                .appendingPathComponent(CredentialStore.unreadableStoreQuarantineName).path))

        // Re-sealed os flavor, location preserved verbatim, revision bumped.
        let raw = try JSONDecoder().decode(
            [String: String].self, from: Data(contentsOf: storeURL))
        #expect(raw.values.allSatisfy { $0.hasPrefix("enc:v2:os:") })
        #expect(raw.keys.contains { $0.hasPrefix(CredentialStore.projectKeyLocationFieldPrefix) })
        #expect(!result.storeLacksProjectLocation)

        // And it round-trips through the read path with the same key.
        let store = try CredentialStore(
            storeURL: storeURL,
            secretURL: base.appendingPathComponent("secret.txt"),
            keychain: keychain)
        #expect(try store.accessToken() == "fresh-access.jwt.payload")
        #expect(try store.value(for: CredentialStore.sessionRevisionField) == "8")
    }

    @Test func saveRefusesToQuarantineWhenKeychainAccessDenied() throws {
        let base = try makeBase()
        defer { try? FileManager.default.removeItem(at: base) }
        let rawKey = Data((0..<32).map { UInt8(($0 * 11) & 0xFF) })
        let storeURL = try seedOSStore(in: base, rawKey: rawKey, revision: 3)
        let account = CredentialStore.keychainAccount(forStoreAt: storeURL)
        let keychain = FakeKeychain(deniedAccounts: [account])

        #expect(throws: CredentialWriteError.keychainAccessDenied) {
            try CredentialStore.saveZaiLogin(
                accessToken: "x", zcodeJwtToken: "y", userInfoJSON: "{}",
                base: base, keychain: keychain)
        }
        // The CLI store is untouched — no quarantine, no rewrite.
        #expect(!FileManager.default.fileExists(
            atPath: storeURL.deletingLastPathComponent()
                .appendingPathComponent(CredentialStore.unreadableStoreQuarantineName).path))
        let raw = try JSONDecoder().decode(
            [String: String].self, from: Data(contentsOf: storeURL))
        #expect(raw[CredentialStore.accessTokenField]?.hasPrefix("enc:v2:os:") == true)
    }

    @Test func virginSaveUsesCLIDiscoverableColocatedSecret() throws {
        let base = try makeBase()
        defer { try? FileManager.default.removeItem(at: base) }
        let v2 = base.appendingPathComponent(".zcode/v2", isDirectory: true)

        _ = try CredentialStore.saveZaiLogin(
            accessToken: "a", zcodeJwtToken: "i", userInfoJSON: "{}", base: base)

        // The secret lands at the CLI's own colocated path, as a valid
        // UTF-8 base64url string (the CLI hashes the file's UTF-8 bytes).
        let secretURL = v2.appendingPathComponent("credential-secret")
        #expect(FileManager.default.fileExists(atPath: secretURL.path))
        let secretString = try #require(
            String(data: try Data(contentsOf: secretURL), encoding: .utf8))
        #expect(secretString.count == 43)
        #expect(secretString.allSatisfy { $0.isLetter || $0.isNumber || $0 == "-" || $0 == "_" })

        // And the store round-trips through the read path with NO
        // keychain item — the colocated file is candidate #1.
        let store = try CredentialStore(
            storeURL: v2.appendingPathComponent("credentials.json"),
            secretURL: base.appendingPathComponent("secret.txt"),
            keychain: FakeKeychain())
        #expect(try store.accessToken() == "a")
        #expect(store.sealingKey?.flavor == .env)
    }

    @Test func saveRefusesToQuarantineWhenKeychainUnavailable() throws {
        let base = try makeBase()
        defer { try? FileManager.default.removeItem(at: base) }
        let rawKey = Data((0..<32).map { UInt8(($0 * 13) & 0xFF) })
        let storeURL = try seedOSStore(in: base, rawKey: rawKey, revision: 5)
        let account = CredentialStore.keychainAccount(forStoreAt: storeURL)
        let keychain = FakeKeychain(unavailableAccounts: [account])

        #expect(throws: CredentialWriteError.keychainUnavailable) {
            try CredentialStore.saveZaiLogin(
                accessToken: "x", zcodeJwtToken: "y", userInfoJSON: "{}",
                base: base, keychain: keychain)
        }
        // The CLI store is untouched — no quarantine, no rewrite.
        #expect(!FileManager.default.fileExists(
            atPath: storeURL.deletingLastPathComponent()
                .appendingPathComponent(CredentialStore.unreadableStoreQuarantineName).path))
        let raw = try JSONDecoder().decode(
            [String: String].self, from: Data(contentsOf: storeURL))
        #expect(raw[CredentialStore.accessTokenField]?.hasPrefix("enc:v2:os:") == true)
    }

    @Test func loginRemedyIsBaseAware() {
        #expect(CredentialStore.loginRemedy(forBase: nil) == CredentialStore.loginRemedy)
        #expect(
            CredentialStore.loginRemedy(forBase: CredentialStore.defaultBase)
                == CredentialStore.loginRemedy)
        let custom = URL(fileURLWithPath: "/opt/zgate-store", isDirectory: true)
        #expect(
            CredentialStore.loginRemedy(forBase: custom)
                == "ZCODE_DATA_BASE_DIR=/opt/zgate-store " + CredentialStore.loginRemedy)
        // The alert surface delegates to the same mapping.
        #expect(
            ReloginAlertContent.command(for: custom)
                == CredentialStore.loginRemedy(forBase: custom))
        #expect(ReloginAlertContent.command(for: nil) == ReloginAlertContent.command)
    }
}

